import React, { useState, useEffect } from 'react';
import PomodoroTimer from './PomodoroTimer';

const Dashboard = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });
  const [tip, setTip] = useState('');

  useEffect(() => {
    const tips = ["ذاكر بذكاء وليس بجهد أكبر.", "خذ استراحة قصيرة كل 25 دقيقة لتجديد نشاطك.", "اشرح ما تعلمته لشخص آخر لتثبيت المعلومة.", "النوم الجيد يساعد على ترسيخ المعلومات في الذاكرة."];
    setTip(tips[Math.floor(Math.random() * tips.length)]);
  }, []);

  const handleMouseMove = (e) => {
    const { innerWidth, innerHeight } = window;
    // حركة خفيفة للصورة بناءً على الماوس
    const x = (e.clientX / innerWidth - 0.5) * 20;
    const y = (e.clientY / innerHeight - 0.5) * 20;
    setOffset({ x, y });
  };

  useEffect(() => {
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // دوال للتعامل مع الأزرار
  const handlePropertiesClick = () => {
    // محاولة العثور على زر المكتبة بأكثر من طريقة لضمان العمل
    const btn = document.querySelector('button[title="العقارات"]') || document.querySelector('button[title="المكتبة"]') || document.querySelector('button[title="الكتب"]');
    if (btn) btn.click();
  };

  const handleContactClick = () => {
    const fab = document.querySelector('.contact-fab');
    if (fab) fab.click();
  };

  const handleLoginClick = () => {
    const btn = document.querySelector('#client-login-button');
    if (btn) btn.click();
  };

  return (
    <div className="container-fluid p-0 overflow-hidden" style={{ minHeight: '80vh' }}>
      <div className="row g-0 align-items-center" style={{ minHeight: '80vh' }}>
        
        {/* القسم النصي */}
        <div className="col-lg-6 p-5 fade-in" style={{ zIndex: 2 }}>
          <div className="p-lg-5">
            <h1 className="display-3 fw-bold mb-4" style={{ background: 'linear-gradient(45deg, #667eea, #764ba2)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent' }}>
              كل الملازم والكتب <br/> اللي محتاجها
            </h1>
            <p className="lead text-muted mb-5" style={{ lineHeight: '1.8' }}>
              أكبر منصة تعليمية في مصر. اطلب مذكراتك وكتبك الخارجية وهتوصلك لحد باب البيت.
              تغطية شاملة لجميع المراحل الدراسية.
            </p>

            <div className="alert alert-warning border-0 shadow-sm mb-4 d-inline-block">
                💡 <strong>نصيحة اليوم:</strong> {tip}
            </div>
            
            <div className="d-flex gap-3 flex-wrap">
              <button className="btn btn-warning text-dark fw-bold btn-lg px-5 rounded-pill shadow-lg" onClick={handlePropertiesClick}>
                تسوق الآن 🛍️
              </button>
              <button className="btn btn-outline-secondary btn-lg px-4 rounded-pill" onClick={handleContactClick}>
                تواصل معنا
              </button>
              <button className="btn btn-success btn-lg px-4 rounded-pill shadow-lg" onClick={handleLoginClick}>
                سجل دخولك الآن
              </button>
            </div>

            <div className="mt-5 pt-4 border-top">
              <div className="row text-center">
                <div className="col">
                  <h3 className="fw-bold text-primary">+1000</h3>
                  <small className="text-muted">مذكرة وكتاب</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+5000</h3>
                  <small className="text-muted">طالب متفوق</small>
                </div>
                <div className="col">
                  <h3 className="fw-bold text-primary">+50</h3>
                  <small className="text-muted">مدرس متميز</small>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* القسم التفاعلي (صورة حقيقية) */}
        <div className="col-lg-6 d-flex justify-content-center align-items-center position-relative" style={{ height: '80vh', perspective: '1000px' }}>
          <div 
            className="house-image-wrapper"
            style={{
              transform: `rotateY(${offset.x / 2}deg) rotateX(${-offset.y / 2}deg)`,
              transition: 'transform 0.1s ease-out',
            }}
          >
            <img 
              src="https://images.unsplash.com/photo-1497633762265-9d179a990aa6?ixlib=rb-4.0.3&auto=format&fit=crop&w=1170&q=80" 
              alt="Books Library" 
              className="img-fluid rounded-4 shadow-lg"
              style={{
                  maxHeight: '60vh',
                  border: '10px solid rgba(255,255,255,0.3)',
                  boxShadow: '0 25px 50px -12px rgba(0, 0, 0, 0.4)'
              }}
            />
          </div>
        </div>
      </div>

      <PomodoroTimer />
      <style>{``}</style>
    </div>
  );
};

export default Dashboard;
